#!/usr/bin/env bash
set -euo pipefail
umask 077
# Belial A3: public observations, PAPER/shadow only. No real orders.
MODE="${1:-}"
if [ "$#" -gt 1 ] || { [ -n "$MODE" ] && [ "$MODE" != "--verificar-pacote" ]; }; then
  echo 'Uso: bash BELIAL_A3_90M_EXECUTAR.sh [--verificar-pacote]' >&2
  exit 2
fi
command -v python3 >/dev/null || { echo 'Python 3 não encontrado. Nada foi instalado.' >&2; exit 2; }
if [ "$(id -u)" -eq 0 ] && [ "$MODE" != "--verificar-pacote" ]; then
  echo 'Execute como usuário normal, sem sudo/root.' >&2
  exit 2
fi
TMP="$(mktemp -d -t belial-a3-90m-XXXXXX)"
cleanup(){ rm -rf -- "$TMP"; }
trap cleanup EXIT
base64 -d > "$TMP/payload.tar.gz" <<'BELIAL_A3_PAYLOAD'
