import hashlib,sys,tarfile,shutil
from pathlib import Path,PurePosixPath
p=Path(sys.argv[1]);destination=Path(sys.argv[2]);expected=sys.argv[3]
if hashlib.sha256(p.read_bytes()).hexdigest()!=expected:raise SystemExit('PAYLOAD_SHA256_MISMATCH')
with tarfile.open(p,'r:gz') as t:
    members=t.getmembers()
    if len(members)>2000 or sum(m.size for m in members)>128*1024*1024:raise SystemExit('PAYLOAD_SIZE_LIMIT')
    seen=set()
    for m in members:
        path=PurePosixPath(m.name)
        if not m.isfile() or path.is_absolute() or '..' in path.parts or not path.parts or path.parts[0]!='BELIAL_A3_90M' or m.name in seen:
            raise SystemExit('UNSAFE_PAYLOAD_MEMBER')
        seen.add(m.name);target=destination.joinpath(*path.parts);target.parent.mkdir(parents=True,exist_ok=True)
        with t.extractfile(m) as src,target.open('xb') as dst:shutil.copyfileobj(src,dst)
print('A3_PAYLOAD_SHA256=PASS; ORDERS=false',flush=True)
PY_EXTRACT
export PYTHONDONTWRITEBYTECODE=1
